pug:
table.row.legal-footer(role='presentation' align='center' width='100%')
    tr
        td.legal-cell(align='center')
            p.legal-warning {{ risk_warning }}
            p.legal-warning {{ company_address }}
            p.legal-links
                a.legal-link(href='{{ terms_link }}' target='_blank') {{ terms_label }}

styl:
.row.legal-footer { background: {{ footer_bg }}; width: 100%; }
.row.legal-footer td.legal-cell { padding: {{ footer_padding }}; text-align: center; }
.row.legal-footer p.legal-warning { font-family: 'Helvetica', 'Arial', sans-serif; font-weight: 400; font-size: 14px; line-height: 21px; color: {{ text_color }}; margin: 0 0 15px; padding: 0; text-align: center; }
.row.legal-footer p.legal-links { margin: 0; padding: 0; text-align: center; }
.row.legal-footer a.legal-link { font-family: 'Helvetica', 'Arial', sans-serif; font-weight: 400; font-size: 14px; color: {{ link_color }}; text-decoration: underline; }
